/**************************************************************************
 * ICLAB 2025FALL / LAB7 PATTERN (NTT)
 * 完整隨機一筆 + 黃金解 + 中間值列印 + 自動對拍 + Timeout 檢查
 **************************************************************************/
`ifdef RTL
  `define CYCLE_TIME_clk1 14.1
  `define CYCLE_TIME_clk2 10.1
  `define CYCLE_TIME_clk3 20.7
`endif
`ifdef GATE
  `define CYCLE_TIME_clk1 14.1
  `define CYCLE_TIME_clk2 10.1
  `define CYCLE_TIME_clk3 20.7
`endif

module PATTERN(
  clk1, clk2, clk3,
  rst_n,
  in_valid,
  in_data,
  out_valid,
  out_data
);
//---------------------------------------------------------------------
//   PORT DECLARATION
//---------------------------------------------------------------------
output reg        clk1, clk2, clk3;
output reg        rst_n;
output reg        in_valid;
output reg [31:0] in_data;

input             out_valid;
input      [15:0] out_data;

//---------------------------------------------------------------------
//   PARAMETER & INTEGER
//---------------------------------------------------------------------
real CYCLE_clk1 = `CYCLE_TIME_clk1;
real CYCLE_clk2 = `CYCLE_TIME_clk2;
real CYCLE_clk3 = `CYCLE_TIME_clk3;

integer total_latency;
integer LAT_MAX = 5000;

// NTT constants (spec)
localparam integer Q    = 12289; // modulus
localparam integer Q0I  = 12287; // Montgomery param (R=2^16)
// degree n = 128 => 7 stages

//---------------------------------------------------------------------
//   REG & WIRE
//---------------------------------------------------------------------
reg  [3:0]  in_poly  [0:127];     // 隨機輸入 0..15
integer     gold_x   [0:127];     // 黃金解工作陣列 (使用整數做模運算)
integer     gold_out [0:127];     // 完成後的輸出
integer     GMb      [0:127];     // twiddle factors

integer i,j,k,s,idx;

//---------------------------------------------------------------------
//  CLOCK
//---------------------------------------------------------------------
always #(CYCLE_clk1/2.0) clk1 = ~clk1;
always #(CYCLE_clk2/2.0) clk2 = ~clk2;
always #(CYCLE_clk3/2.0) clk3 = ~clk3;

initial begin
  clk1 = 0; clk2 = 0; clk3 = 0;
end

//---------------------------------------------------------------------
//  INITIAL : one test
//---------------------------------------------------------------------
initial begin
  rst_n       = 1'bx;
  in_valid    = 1'bx;
  in_data     = 32'dx;
  total_latency = 0;

  // reset
  repeat(2) @(negedge clk1);
  rst_n    = 1'b0;
  in_valid = 1'b0;
  in_data  = 32'd0;

  // reset期間/剛起跑，輸出必為0
  repeat (3) begin
    @(posedge clk1);
    if (out_valid !== 1'b0 || out_data !== 16'd0) begin
      $display("** ERROR ** out must be 0 during reset/initial!");
      $finish;
    end
  end
  $display("[INFO] Reset done.");
  rst_n = 1'b1;

  // 讀 GMb
  load_gmb("../00_TESTBED/GMb.txt");
	$display("[INFO] GMb loaded.");
  // 產生一筆隨機輸入
  gen_random_input();
	$display("[INFO] Random input generated.");

  //  Debug 標頭
  $display("\n==================================================");
  $display(" [DEBUG] Computing Golden Reference Before DUT");
  $display("==================================================");

  // 算黃金解 (同時印每一層的 x[])
  compute_ntt_and_debug();

  //  Debug 標頭
  $display("\n==================================================");
  $display(" [DEBUG] Sending Input to DUT...");
  $display("==================================================");

  // 送進 DUT
  send_input_to_dut();

  //  Debug 標頭
  $display("\n==================================================");
  $display(" [DEBUG] Waiting for DUT Output (max %0d clk3)...", LAT_MAX);
  $display("==================================================");

  // 收 & 對拍（含 timeout）
  check_output_and_score();

  // 結束
  YOU_PASS_task;
end

//---------------------------------------------------------------------
//  TASK / FUNCTION
//---------------------------------------------------------------------

// ✅ 改良版：讀 GMb（支援註解與空白行，不會卡死）
task load_gmb(input [1023:0] path);
  integer f, val, cnt;
  reg [255:0] line;
begin
  for (cnt=0; cnt<128; cnt=cnt+1) GMb[cnt]=0;
  f = $fopen(path, "r");
  if (f==0) begin
    $display("** ERROR ** cannot open GMb file: %s", path);
    $finish;
  end
  cnt = 0;
  while (!$feof(f) && cnt<128) begin
    if ($fgets(line, f)) begin
      // 跳過註解或空白行
      if (line[255:248] == "//" || line == "") continue;
      if ($sscanf(line, "%d", val) == 1) begin
        GMb[cnt] = val;
        cnt = cnt + 1;
      end
    end
  end
  $fclose(f);
  if (cnt!=128) begin
    $display("** ERROR ** GMb count != 128 (got %0d)", cnt);
    $finish;
  end
  $display("[INFO] Loaded %0d GMb values successfully.", cnt);
end
endtask

// 產生 128 個 0..15 的無號係數
task gen_random_input;
  integer t;
begin
  for (t=0; t<128; t=t+1) begin
    in_poly[t] = $urandom_range(0,15);
    gold_x[t]  = in_poly[t]; // 初始化黃金解工作陣列
  end
  $display("\n=== INPUT x[0..127] (4-bit each) ===");
  print_array_16x8_int(gold_x);
end
endtask

// 輸入送進 DUT（clk1）
task send_input_to_dut;
  integer cyc, n;
  reg [31:0] word;
begin
  @(negedge clk1);
  in_valid = 1'b1;
  for (cyc=0; cyc<16; cyc=cyc+1) begin
    word = 32'd0;
    for (n=0; n<8; n=n+1) begin
      word = word | ( {28'd0, in_poly[cyc*8+n]} << (4*n) );
    end
    in_data = word;
    @(negedge clk1);

    // 規格：in_valid 高時，輸出必為零
    if (out_valid !== 1'b0 || out_data !== 16'd0) begin
      $display("** ERROR ** out must be zero while in_valid=1 (cycle %0d)", cyc);
      $finish;
    end
  end
  in_valid = 1'b0;
  in_data  = 32'd0;
end
endtask

// 蒙哥馬利乘法 (a*b mod Q)
function automatic integer modq_mul(input integer a, input integer b);
  reg [63:0] x, y, z;
begin
  x = (64'd0 + a) * (64'd0 + b);
  y = (x * Q0I) & 64'hFFFF;
  z = (x + y*Q) >> 16;
  if (z >= Q) modq_mul = z - Q; else modq_mul = z;
end
endfunction

function automatic integer mod_add(input integer u, input integer v);
  integer r;
begin
  r = u + v;
  if (r >= Q) r = r - Q;
  mod_add = r;
end
endfunction

function automatic integer mod_sub(input integer u, input integer v);
  integer r;
begin
  if (u >= v) r = u - v;
  else        r = u - v + Q;
  mod_sub = r;
end
endfunction

// 列印 128 筆整數
task print_array_16x8_int(input integer arr[0:127]);
  integer p,q;
begin
  for (p=0; p<16; p=p+1) begin
    $write("  [%02d..%02d] :", p*8, p*8+7);
    for (q=0; q<8; q=q+1) $write(" %5d", arr[p*8+q]);
    $write("\n");
  end
end
endtask

// Golden NTT 計算 (含中間層輸出)
task compute_ntt_and_debug;
  integer t, m, ht, i_, j1, sidx, j2_, j_;
  integer u_, v_;
  integer stage;
begin
  $display("\n=== BEGIN NTT GOLDEN (Q=%0d, Q0I=%0d) ===", Q, Q0I);

  t = 128;
  stage = 0;
  for (m = 1; m < 128; m = m*2) begin
    stage = stage + 1;
    ht = t >> 1; // t/2
    for (i_=0, j1=0; i_ < m; i_=i_+1, j1=j1 + t) begin
      sidx = GMb[m + i_];  // s = GMb[m+i]
      j2_  = j1 + ht;
      for (j_=j1; j_<j2_; j_=j_+1) begin
        u_ = gold_x[j_];
        v_ = modq_mul(gold_x[j_ + ht], sidx);
        gold_x[j_]        = mod_add(u_, v_);
        gold_x[j_ + ht]   = mod_sub(u_, v_);
      end
    end
    t = ht;

    // 每層結束印出
    $display("\n--- Stage %0d done (m=%0d, ht=%0d) ---", stage, m, ht);
    print_array_16x8_int(gold_x);
  end

  for (k=0; k<128; k=k+1) gold_out[k] = gold_x[k];
  $display("\n=== END NTT GOLDEN ===\n");
end
endtask

// 收出與對拍，含 Timeout 防卡
task check_output_and_score;
  integer got, err;
begin
  got = 0;
  err = 0;
  total_latency = 0;

  while (got < 128) begin
    @(posedge clk3);
    total_latency = total_latency + 1;

    if (out_valid) begin
      $display("[Compare] idx=%0d : DUT=%0d, GOLD=%0d", got, out_data, gold_out[got]);
      if (out_data !== gold_out[got][15:0]) begin
        $display("** MISMATCH ** idx=%0d  DUT=%0d  GOLD=%0d", got, out_data, gold_out[got]);
